  const result = issueInvoice(invoice, []).value;
  assert.equal(result.customerId, 'C-003');
  assert.equal(result.issueDate, '2025-12-25');
  assert.equal(result.lines.length, 2);
  assert.equal(result.lines[0].sku, 'DES-HOUR');
  assert.equal(result.lines[1].sku, 'DEV-HOUR');
});

